,"definition":"CREATE OR REPLACE FUNCTION pg_catalog.\"RI_FKey_noaction_upd\"()\n RETURNS trigger\n LANGUAGE internal\n PARALLEL SAFE STRICT\nAS $function$RI_FKey_noaction_upd$function$\n","identity":{"arguments":"","name":"RI_FKey_noaction_upd","schema":"pg_catalog"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"internal","leakproof":false,"ownerRef":"original_pg17_bootstrap_owner","parallel":"s","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"RI_FKey_noaction_upd","sqlBody":null,"strict":true,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":["search_path=pg_catalog","lock_timeout=5s"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.maintain_thread_run_occupancy()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\n SET lock_timeout TO ''5s''\nAS $function$\nDECLARE\n    old_occupied boolean;\n    new_occupied boolean;\n    removed bigint;\nBEGIN\n    IF TG_OP = ''INSERT'' THEN\n        new_occupied := NEW.foreground AND NEW.status IN (''queued'', ''running'', ''reconciliation_required'');\n        IF new_occupied THEN\n            IF EXISTS (SELECT 1 FROM public.thread_run_occupancy\n                       WHERE thread_id = NEW.thread_id OR run_id = NEW.run_id) THEN\n                RAISE EXCEPTION USING ERRCODE = ''23514'',\n                    CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n            END IF;\n            INSERT INTO public.thread_run_occupancy(thread_id, run_id) VALUES (NEW.thread_id, NEW.run_id);\n        ELSIF EXISTS (SELECT 1 FROM public.thread_run_occupancy WHERE run_id = NEW.run_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n        RETURN NULL;\n    END IF;\n\n    old_occupied := OLD.foreground AND OLD.status IN (''queued'', ''running'', ''reconciliation_required'');\n    IF TG_OP = ''DELETE'' THEN\n        IF old_occupied OR OLD.status = ''reconciliation_required'' THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_release_forbidden'', MESSAGE = ''occupancy release forbidden'';\n        END IF;\n        IF EXISTS (SELECT 1 FROM public.thread_run_occupancy WHERE run_id = OLD.run_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n        RETURN NULL;\n    END IF;\n\n    IF NEW.run_id IS DISTINCT FROM OLD.run_id OR NEW.thread_id IS DISTINCT FROM OLD.thread_id\n       OR NEW.foreground IS DISTINCT FROM OLD.foreground THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_identity_immutable'', MESSAGE = ''occupancy identity immutable'';\n    END IF;\n    IF OLD.status = ''reconciliation_required'' AND NEW.status IS DISTINCT FROM OLD.status THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_rr_immutable'', MESSAGE = ''reconciliation status immutable'';\n    END IF;\n    IF OLD.status IN (''completed'', ''failed'', ''cancelled'')\n       AND NEW.status IN (''queued'', ''running'', ''reconciliation_required'') THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_terminal_reactivation'', MESSAGE = ''terminal reactivation forbidden'';\n    END IF;\n    new_occupied := NEW.foreground AND NEW.status IN (''queued'', ''running'', ''reconciliation_required'');\n    IF old_occupied THEN\n        -- Only this run''s exact slot is locked, after the caller''s original run DML.\n        PERFORM 1 FROM public.thread_run_occupancy\n            WHERE thread_id = OLD.thread_id AND run_id = OLD.run_id FOR UPDATE NOWAIT;\n        IF NOT FOUND THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_missing'', MESSAGE = ''occupancy pair missing'';\n        END IF;\n        IF EXISTS (SELECT 1 FROM public.thread_run_occupancy\n                   WHERE run_id = OLD.run_id AND thread_id <> OLD.thread_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n        IF NOT new_occupied THEN\n            IF NEW.status NOT IN (''completed'', ''failed'', ''cancelled'') THEN\n                RAISE EXCEPTION USING ERRCODE = ''23514'',\n                    CONSTRAINT = ''thread_run_occupancy_release_forbidden'', MESSAGE = ''occupancy release forbidden'';\n            END IF;\n            DELETE FROM public.thread_run_occupancy\n                WHERE thread_id = OLD.thread_id AND run_id = OLD.run_id;\n            GET DIAGNOSTICS removed = ROW_COUNT;\n            IF removed <> 1 THEN\n                RAISE EXCEPTION USING ERRCODE = ''23514'',\n                    CONSTRAINT = ''thread_run_occupancy_pair_missing'', MESSAGE = ''occupancy pair missing'';\n            END IF;\n        END IF;\n    ELSE\n        IF new_occupied OR EXISTS (SELECT 1 FROM public.thread_run_occupancy WHERE run_id = OLD.run_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n    END IF;\n    RETURN NULL;\nEND;\n$function$\n","identity":{"arguments":"","name":"maintain_thread_run_occupancy","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE\n    old_occupied boolean;\n    new_occupied boolean;\n    removed bigint;\nBEGIN\n    IF TG_OP = ''INSERT'' THEN\n        new_occupied := NEW.foreground AND NEW.status IN (''queued'', ''running'', ''reconciliation_required'');\n        IF new_occupied THEN\n            IF EXISTS (SELECT 1 FROM public.thread_run_occupancy\n                       WHERE thread_id = NEW.thread_id OR run_id = NEW.run_id) THEN\n                RAISE EXCEPTION USING ERRCODE = ''23514'',\n                    CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n            END IF;\n            INSERT INTO public.thread_run_occupancy(thread_id, run_id) VALUES (NEW.thread_id, NEW.run_id);\n        ELSIF EXISTS (SELECT 1 FROM public.thread_run_occupancy WHERE run_id = NEW.run_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n        RETURN NULL;\n    END IF;\n\n    old_occupied := OLD.foreground AND OLD.status IN (''queued'', ''running'', ''reconciliation_required'');\n    IF TG_OP = ''DELETE'' THEN\n        IF old_occupied OR OLD.status = ''reconciliation_required'' THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_release_forbidden'', MESSAGE = ''occupancy release forbidden'';\n        END IF;\n        IF EXISTS (SELECT 1 FROM public.thread_run_occupancy WHERE run_id = OLD.run_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n        RETURN NULL;\n    END IF;\n\n    IF NEW.run_id IS DISTINCT FROM OLD.run_id OR NEW.thread_id IS DISTINCT FROM OLD.thread_id\n       OR NEW.foreground IS DISTINCT FROM OLD.foreground THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_identity_immutable'', MESSAGE = ''occupancy identity immutable'';\n    END IF;\n    IF OLD.status = ''reconciliation_required'' AND NEW.status IS DISTINCT FROM OLD.status THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_rr_immutable'', MESSAGE = ''reconciliation status immutable'';\n    END IF;\n    IF OLD.status IN (''completed'', ''failed'', ''cancelled'')\n       AND NEW.status IN (''queued'', ''running'', ''reconciliation_required'') THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_terminal_reactivation'', MESSAGE = ''terminal reactivation forbidden'';\n    END IF;\n    new_occupied := NEW.foreground AND NEW.status IN (''queued'', ''running'', ''reconciliation_required'');\n    IF old_occupied THEN\n        -- Only this run''s exact slot is locked, after the caller''s original run DML.\n        PERFORM 1 FROM public.thread_run_occupancy\n            WHERE thread_id = OLD.thread_id AND run_id = OLD.run_id FOR UPDATE NOWAIT;\n        IF NOT FOUND THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_missing'', MESSAGE = ''occupancy pair missing'';\n        END IF;\n        IF EXISTS (SELECT 1 FROM public.thread_run_occupancy\n                   WHERE run_id = OLD.run_id AND thread_id <> OLD.thread_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n        IF NOT new_occupied THEN\n            IF NEW.status NOT IN (''completed'', ''failed'', ''cancelled'') THEN\n                RAISE EXCEPTION USING ERRCODE = ''23514'',\n                    CONSTRAINT = ''thread_run_occupancy_release_forbidden'', MESSAGE = ''occupancy release forbidden'';\n            END IF;\n            DELETE FROM public.thread_run_occupancy\n                WHERE thread_id = OLD.thread_id AND run_id = OLD.run_id;\n            GET DIAGNOSTICS removed = ROW_COUNT;\n            IF removed <> 1 THEN\n                RAISE EXCEPTION USING ERRCODE = ''23514'',\n                    CONSTRAINT = ''thread_run_occupancy_pair_missing'', MESSAGE = ''occupancy pair missing'';\n            END IF;\n        END IF;\n    ELSE\n        IF new_occupied OR EXISTS (SELECT 1 FROM public.thread_run_occupancy WHERE run_id = OLD.run_id) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_unexpected'', MESSAGE = ''occupancy pair unexpected'';\n        END IF;\n    END IF;\n    RETURN NULL;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":["search_path=pg_catalog"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.guard_thread_run_occupancy()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog''\nAS $function$\nBEGIN\n    IF TG_OP = ''TRUNCATE'' THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_no_truncate'', MESSAGE = ''occupancy truncate forbidden'';\n    END IF;\n    -- Depth prevents accidental direct SQL; it grants no authority against a DDL-capable DB owner.\n    IF TG_OP = ''UPDATE'' OR pg_trigger_depth() < 2 THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_direct_write'', MESSAGE = ''direct occupancy write forbidden'';\n    END IF;\n    IF TG_OP = ''INSERT'' THEN\n        IF NOT EXISTS (SELECT 1 FROM public.runs WHERE run_id = NEW.run_id AND thread_id = NEW.thread_id\n                       AND foreground AND status IN (''queued'', ''running'', ''reconciliation_required'')) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_invalid'', MESSAGE = ''occupancy pair invalid'';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.runs WHERE run_id = OLD.run_id AND thread_id = OLD.thread_id\n                   AND foreground AND status IN (''completed'', ''failed'', ''cancelled'')) THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_release_forbidden'', MESSAGE = ''occupancy release forbidden'';\n    END IF;\n    RETURN OLD;\nEND;\n$function$\n","identity":{"arguments":"","name":"guard_thread_run_occupancy","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nBEGIN\n    IF TG_OP = ''TRUNCATE'' THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_no_truncate'', MESSAGE = ''occupancy truncate forbidden'';\n    END IF;\n    -- Depth prevents accidental direct SQL; it grants no authority against a DDL-capable DB owner.\n    IF TG_OP = ''UPDATE'' OR pg_trigger_depth() < 2 THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_direct_write'', MESSAGE = ''direct occupancy write forbidden'';\n    END IF;\n    IF TG_OP = ''INSERT'' THEN\n        IF NOT EXISTS (SELECT 1 FROM public.runs WHERE run_id = NEW.run_id AND thread_id = NEW.thread_id\n                       AND foreground AND status IN (''queued'', ''running'', ''reconciliation_required'')) THEN\n            RAISE EXCEPTION USING ERRCODE = ''23514'',\n                CONSTRAINT = ''thread_run_occupancy_pair_invalid'', MESSAGE = ''occupancy pair invalid'';\n        END IF;\n        RETURN NEW;\n    END IF;\n    IF NOT EXISTS (SELECT 1 FROM public.runs WHERE run_id = OLD.run_id AND thread_id = OLD.thread_id\n                   AND foreground AND status IN (''completed'', ''failed'', ''cancelled'')) THEN\n        RAISE EXCEPTION USING ERRCODE = ''23514'',\n            CONSTRAINT = ''thread_run_occupancy_release_forbidden'', MESSAGE = ''occupancy release forbidden'';\n    END IF;\n    RETURN OLD;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":null,"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.bind_thread_history_head_on_insert()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE v_base public.threads%ROWTYPE;\n v_head openbot_internal.thread_history_heads%ROWTYPE;\n v_base_found boolean;\n v_inserted text;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''threads'' OR TG_OP<>''INSERT'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n SELECT t.* INTO v_base FROM public.threads t WHERE t.thread_id=NEW.thread_id FOR SHARE OF t;\n v_base_found:=FOUND;\n IF v_base_found THEN\n  IF ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at) IS DISTINCT FROM ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.anchor_kind,NEW.anchor_id,NEW.created_at) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n  END IF;\n  INSERT INTO openbot_internal.thread_history_heads (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at) VALUES (v_base.deployment_id,v_base.tenant_id,v_base.thread_id,1,''open'',v_base.anchor_kind,v_base.anchor_id,v_base.created_at) ON CONFLICT(thread_id) DO NOTHING;\n  SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n   WHERE h.thread_id=NEW.thread_id FOR SHARE OF h;\n  IF NOT FOUND OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n  END IF;\n  RETURN NEW;\n END IF;\n IF EXISTS(SELECT 1 FROM openbot_internal.thread_origins o WHERE o.thread_id=NEW.thread_id) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_identity_reuse_refused'';\n END IF;\n INSERT INTO openbot_internal.thread_history_heads (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at) VALUES (NEW.deployment_id,NEW.tenant_id,NEW.thread_id,1,''open'',NEW.anchor_kind,NEW.anchor_id,NEW.created_at) ON CONFLICT(thread_id) DO NOTHING RETURNING thread_id INTO v_inserted;\n IF v_inserted IS NOT NULL THEN\n  RETURN NEW;\n END IF;\n SELECT t.* INTO v_base FROM public.threads t WHERE t.thread_id=NEW.thread_id FOR SHARE OF t;\n IF NOT FOUND THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_identity_reuse_refused'';\n END IF;\n SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=NEW.thread_id FOR SHARE OF h;\n IF NOT FOUND OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at)\n    OR ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.anchor_kind,NEW.anchor_id,NEW.created_at) IS DISTINCT FROM ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n$function$\n","identity":{"arguments":"","name":"bind_thread_history_head_on_insert","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_base public.threads%ROWTYPE;\n v_head openbot_internal.thread_history_heads%ROWTYPE;\n v_base_found boolean;\n v_inserted text;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''threads'' OR TG_OP<>''INSERT'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n SELECT t.* INTO v_base FROM public.threads t WHERE t.thread_id=NEW.thread_id FOR SHARE OF t;\n v_base_found:=FOUND;\n IF v_base_found THEN\n  IF ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at) IS DISTINCT FROM ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.anchor_kind,NEW.anchor_id,NEW.created_at) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n  END IF;\n  INSERT INTO openbot_internal.thread_history_heads (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at) VALUES (v_base.deployment_id,v_base.tenant_id,v_base.thread_id,1,''open'',v_base.anchor_kind,v_base.anchor_id,v_base.created_at) ON CONFLICT(thread_id) DO NOTHING;\n  SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n   WHERE h.thread_id=NEW.thread_id FOR SHARE OF h;\n  IF NOT FOUND OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n  END IF;\n  RETURN NEW;\n END IF;\n IF EXISTS(SELECT 1 FROM openbot_internal.thread_origins o WHERE o.thread_id=NEW.thread_id) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_identity_reuse_refused'';\n END IF;\n INSERT INTO openbot_internal.thread_history_heads (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at) VALUES (NEW.deployment_id,NEW.tenant_id,NEW.thread_id,1,''open'',NEW.anchor_kind,NEW.anchor_id,NEW.created_at) ON CONFLICT(thread_id) DO NOTHING RETURNING thread_id INTO v_inserted;\n IF v_inserted IS NOT NULL THEN\n  RETURN NEW;\n END IF;\n SELECT t.* INTO v_base FROM public.threads t WHERE t.thread_id=NEW.thread_id FOR SHARE OF t;\n IF NOT FOUND THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_identity_reuse_refused'';\n END IF;\n SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=NEW.thread_id FOR SHARE OF h;\n IF NOT FOUND OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at)\n    OR ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.anchor_kind,NEW.anchor_id,NEW.created_at) IS DISTINCT FROM ROW(v_base.deployment_id,v_base.tenant_id,v_base.thread_id,v_base.anchor_kind,v_base.anchor_id,v_base.created_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":null,"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.guard_thread_history_head_mutation()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''thread_history_heads''\n    OR TG_OP NOT IN(''UPDATE'',''DELETE'',''TRUNCATE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\n END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF OLD.phase=''open'' AND NEW.phase=''closed''\n     AND ROW(OLD.deployment_id,OLD.tenant_id,OLD.thread_id,OLD.head_schema,OLD.anchor_kind,OLD.anchor_id,OLD.thread_created_at,OLD.recorded_at) IS NOT DISTINCT FROM ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.head_schema,NEW.anchor_kind,NEW.anchor_id,NEW.thread_created_at,NEW.recorded_at) THEN\n   RETURN NEW;\n  END IF;\n END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\nEND;\n$function$\n","identity":{"arguments":"","name":"guard_thread_history_head_mutation","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''thread_history_heads''\n    OR TG_OP NOT IN(''UPDATE'',''DELETE'',''TRUNCATE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\n END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF OLD.phase=''open'' AND NEW.phase=''closed''\n     AND ROW(OLD.deployment_id,OLD.tenant_id,OLD.thread_id,OLD.head_schema,OLD.anchor_kind,OLD.anchor_id,OLD.thread_created_at,OLD.recorded_at) IS NOT DISTINCT FROM ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.head_schema,NEW.anchor_kind,NEW.anchor_id,NEW.thread_created_at,NEW.recorded_at) THEN\n   RETURN NEW;\n  END IF;\n END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argu