n LANGUAGE plpgsql\nAS $function$\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''thread_history_clear_intents''\n    OR TG_OP NOT IN(''UPDATE'',''DELETE'',''TRUNCATE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\n END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\nEND;\n$function$\n","identity":{"arguments":"","name":"prevent_thread_history_intent_mutation","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''thread_history_clear_intents''\n    OR TG_OP NOT IN(''UPDATE'',''DELETE'',''TRUNCATE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\n END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_mutation_refused'';\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":null,"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.protect_thread_history_base_identity()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE v_head openbot_internal.thread_history_heads%ROWTYPE;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''threads'' OR TG_OP<>''UPDATE'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n IF NEW.thread_id IS DISTINCT FROM OLD.thread_id THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_identity_reuse_refused'';\n END IF;\n SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=OLD.thread_id FOR SHARE OF h;\n IF FOUND AND (ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(OLD.deployment_id,OLD.tenant_id,OLD.thread_id,OLD.anchor_kind,OLD.anchor_id,OLD.created_at)\n     OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.anchor_kind,NEW.anchor_id,NEW.created_at)) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n$function$\n","identity":{"arguments":"","name":"protect_thread_history_base_identity","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_head openbot_internal.thread_history_heads%ROWTYPE;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''threads'' OR TG_OP<>''UPDATE'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n IF NEW.thread_id IS DISTINCT FROM OLD.thread_id THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_identity_reuse_refused'';\n END IF;\n SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=OLD.thread_id FOR SHARE OF h;\n IF FOUND AND (ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(OLD.deployment_id,OLD.tenant_id,OLD.thread_id,OLD.anchor_kind,OLD.anchor_id,OLD.created_at)\n     OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(NEW.deployment_id,NEW.tenant_id,NEW.thread_id,NEW.anchor_kind,NEW.anchor_id,NEW.created_at)) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":null,"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.require_thread_history_intent_closed_head()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE v_matches boolean;\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''thread_history_clear_intents''\n    OR TG_OP<>''INSERT'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n SELECT true INTO v_matches FROM openbot_internal.thread_history_heads h\n WHERE h.deployment_id=NEW.deployment_id AND h.tenant_id=NEW.tenant_id\n   AND h.thread_id=NEW.thread_id AND h.phase=''closed''\n   AND h.closure_operation_id=NEW.operation_id AND h.closure_request_id=NEW.request_id\n   AND h.closure_actor_id=NEW.actor_id AND h.closure_auth_generation=NEW.auth_generation\n   AND h.anchor_kind=NEW.anchor_kind AND h.anchor_id=NEW.anchor_id\n   AND h.thread_created_at=NEW.thread_created_at AND h.closed_at=NEW.recorded_at\n FOR SHARE OF h;\n IF v_matches IS DISTINCT FROM true THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n$function$\n","identity":{"arguments":"","name":"require_thread_history_intent_closed_head","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_matches boolean;\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''thread_history_clear_intents''\n    OR TG_OP<>''INSERT'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n SELECT true INTO v_matches FROM openbot_internal.thread_history_heads h\n WHERE h.deployment_id=NEW.deployment_id AND h.tenant_id=NEW.tenant_id\n   AND h.thread_id=NEW.thread_id AND h.phase=''closed''\n   AND h.closure_operation_id=NEW.operation_id AND h.closure_request_id=NEW.request_id\n   AND h.closure_actor_id=NEW.actor_id AND h.closure_auth_generation=NEW.auth_generation\n   AND h.anchor_kind=NEW.anchor_kind AND h.anchor_id=NEW.anchor_id\n   AND h.thread_created_at=NEW.thread_created_at AND h.closed_at=NEW.recorded_at\n FOR SHARE OF h;\n IF v_matches IS DISTINCT FROM true THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"PUBLIC","grantor":"original_threads_owner","privilege":"EXECUTE"},{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":true,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":null,"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.retain_thread_history_head_on_delete()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE v_head openbot_internal.thread_history_heads%ROWTYPE;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''threads'' OR TG_OP<>''DELETE'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n INSERT INTO openbot_internal.thread_history_heads (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at) VALUES (OLD.deployment_id,OLD.tenant_id,OLD.thread_id,1,''open'',OLD.anchor_kind,OLD.anchor_id,OLD.created_at) ON CONFLICT(thread_id) DO NOTHING;\n SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=OLD.thread_id FOR SHARE OF h;\n IF NOT FOUND OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(OLD.deployment_id,OLD.tenant_id,OLD.thread_id,OLD.anchor_kind,OLD.anchor_id,OLD.created_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN OLD;\nEND;\n$function$\n","identity":{"arguments":"","name":"retain_thread_history_head_on_delete","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":null,"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_head openbot_internal.thread_history_heads%ROWTYPE;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''threads'' OR TG_OP<>''DELETE'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n INSERT INTO openbot_internal.thread_history_heads (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at) VALUES (OLD.deployment_id,OLD.tenant_id,OLD.thread_id,1,''open'',OLD.anchor_kind,OLD.anchor_id,OLD.created_at) ON CONFLICT(thread_id) DO NOTHING;\n SELECT h.* INTO v_head FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=OLD.thread_id FOR SHARE OF h;\n IF NOT FOUND OR ROW(v_head.deployment_id,v_head.tenant_id,v_head.thread_id,v_head.anchor_kind,v_head.anchor_id,v_head.thread_created_at) IS DISTINCT FROM ROW(OLD.deployment_id,OLD.tenant_id,OLD.thread_id,OLD.anchor_kind,OLD.anchor_id,OLD.created_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_state_binding_invalid'';\n END IF;\n RETURN OLD;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_channel","p_strict_absence"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_validate_channel_final(p_channel text, p_strict_absence boolean)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_c public.channels%ROWTYPE;v_s openbot_internal.channel_history_sources%ROWTYPE;\n v_channel_found boolean;v_source_found boolean;v_preview text;\nBEGIN\n SELECT c.* INTO v_c FROM public.channels c WHERE c.id=p_channel FOR UPDATE OF c NOWAIT;\n v_channel_found:=FOUND;\n SELECT s.* INTO v_s FROM openbot_internal.channel_history_sources s WHERE s.channel_id=p_channel;\n v_source_found:=FOUND;\n IF NOT v_channel_found THEN\n  IF v_source_found THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n  RETURN;\n END IF;\n IF NOT v_source_found THEN\n  IF p_strict_absence AND ROW(v_c.last_message,v_c.last_message_at,v_c.last_message_agent_id)\n      IS DISTINCT FROM ROW(NULL::text,NULL::timestamptz,NULL::text) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN;\n END IF;\n PERFORM openbot_internal.thread_history_validate_channel_source(v_s,false);\n SELECT openbot_internal.thread_history_preview(m.search_text) INTO v_preview\n  FROM public.messages m WHERE m.message_id=v_s.message_id;\n IF NOT FOUND OR ROW(v_c.last_message,v_c.last_message_at,v_c.last_message_agent_id)\n      IS DISTINCT FROM ROW(v_preview,v_s.message_created_at,v_s.last_message_agent_id) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\nEND;\n$function$\n","identity":{"arguments":"p_channel text, p_strict_absence boolean","name":"thread_history_validate_channel_final","schema":"openbot_internal"},"inputArgumentCount":2,"inputTypes":[{"name":"text","ordinal":1,"schema":"pg_catalog"},{"name":"bool","ordinal":2,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"void","name":"void","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_c public.channels%ROWTYPE;v_s openbot_internal.channel_history_sources%ROWTYPE;\n v_channel_found boolean;v_source_found boolean;v_preview text;\nBEGIN\n SELECT c.* INTO v_c FROM public.channels c WHERE c.id=p_channel FOR UPDATE OF c NOWAIT;\n v_channel_found:=FOUND;\n SELECT s.* INTO v_s FROM openbot_internal.channel_history_sources s WHERE s.channel_id=p_channel;\n v_source_found:=FOUND;\n IF NOT v_channel_found THEN\n  IF v_source_found THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n  RETURN;\n END IF;\n IF NOT v_source_found THEN\n  IF p_strict_absence AND ROW(v_c.last_message,v_c.last_message_at,v_c.last_message_agent_id)\n      IS DISTINCT FROM ROW(NULL::text,NULL::timestamptz,NULL::text) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN;\n END IF;\n PERFORM openbot_internal.thread_history_validate_channel_source(v_s,false);\n SELECT openbot_internal.thread_history_preview(m.search_text) INTO v_preview\n  FROM public.messages m WHERE m.message_id=v_s.message_id;\n IF NOT FOUND OR ROW(v_c.last_message,v_c.last_message_at,v_c.last_message_agent_id)\n      IS DISTINCT FROM ROW(v_preview,v_s.message_created_at,v_s.last_message_agent_id) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_ids"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_lock_channel_ids(p_ids text[])\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_id text;v_found text;\nBEGIN\n FOR v_id IN SELECT DISTINCT x COLLATE pg_catalog.\"C\" FROM pg_catalog.unnest(p_ids) x\n             WHERE x IS NOT NULL ORDER BY x COLLATE pg_catalog.\"C\" LOOP\n  SELECT c.id INTO v_found FROM public.channels c WHERE c.id=v_id FOR UPDATE OF c NOWAIT;\n  IF NOT FOUND THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n END LOOP;\nEND;\n$function$\n","identity":{"arguments":"p_ids text[]","name":"thread_history_lock_channel_ids","schema":"openbot_internal"},"inputArgumentCount":1,"inputTypes":[{"name":"_text","ordinal":1,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"void","name":"void","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_id text;v_found text;\nBEGIN\n FOR v_id IN SELECT DISTINCT x COLLATE pg_catalog.\"C\" FROM pg_catalog.unnest(p_ids) x\n             WHERE x IS NOT NULL ORDER BY x COLLATE pg_catalog.\"C\" LOOP\n  SELECT c.id INTO v_found FROM public.channels c WHERE c.id=v_id FOR UPDATE OF c NOWAIT;\n  IF NOT FOUND THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n END LOOP;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_run","p_terminal_changed"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_validate_terminal_run(p_run text, p_terminal_changed boolean)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_r public.runs%ROWTYPE;v_e public.run_events%ROWTYPE;v_event_found boolean;v_open boolean;\nBEGIN\n IF p_terminal_changed IS NULL THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n SELECT r.* INTO v_r FROM public.runs r WHERE r.run_id=p_run FOR SHARE OF r NOWAIT;\n IF NOT FOUND THEN\n  IF EXISTS(SELECT 1 FROM public.run_events e WHERE e.run_id=p_run AND e.terminal) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN;\n END IF;\n v_open:=openbot_internal.thread_history_lock_joint(v_r.thread_id,v_r.run_id);\n SELECT e.run_id,e.thread_id,e.event_type,e.seq\n  INTO v_e.run_id,v_e.thread_id,v_e.event_type,v_e.seq\n  FROM public.run_events e WHERE e.run_id=p_run AND e.terminal FOR SHARE OF e NOWAIT;\n v_event_found:=FOUND;\n IF v_r.status IN(''queued'',''running'') THEN\n  IF v_event_found THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n  RETURN;\n END IF;\n IF v_r.status NOT IN(''completed'',''failed'',''cancelled'',''reconciliation_required'') OR NOT v_event_found OR\n    ROW(v_r.run_id,v_r.thread_id,v_r.status,v_r.terminal_event_seq)\n     IS DISTINCT FROM ROW(v_e.run_id,v_e.thread_id,v_e.event_type,v_e.seq) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- Preserve the original open-J import contract: its verified bundle allows an\n -- arbitrary object terminal payload and valid historical error identifier. The\n -- fixed21-code payload is only the actual changed CLOSED terminal exception,\n -- not a new open import validator or revalidation of unchanged historical body.\n -- Nonterminal scrubs and terminal metadata do not read that historical payload.\n -- The final Run/event identity/status/sequence joint above is shared.\n IF v_open OR NOT p_terminal_changed THEN RETURN;END IF;\n SELECT e.payload INTO v_e.payload FROM public.run_events e\n  WHERE e.run_id=v_e.run_id AND e.seq=v_e.seq AND e.terminal FOR SHARE OF e NOWAIT;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n IF NOT openbot_internal.thread_history_terminal_payload(v_e.event_type,v_e.payload) OR\n    v_r.error_code IS DISTINCT FROM v_e.payload->>''errorCode'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\nEND;\n$function$\n","identity":{"arguments":"p_run text, p_terminal_changed boolean","name":"thread_history_validate_terminal_run","schema":"openbot_internal"},"inputArgumentCount":2,"inputTypes":[{"name":"text","ordinal":1,"schema":"pg_catalog"},{"name":"bool","ordinal":2,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"void","name":"void","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_r public.runs%ROWTYPE;v_e public.run_events%ROWTYPE;v_event_found boolean;v_open boolean;\nBEGIN\n IF p_terminal_changed IS NULL THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n SELECT r.* INTO v_r FROM public.runs r WHERE r.run_id=p_run FOR SHARE OF r NOWAIT;\n IF NOT FOUND THEN\n  IF EXISTS(SELECT 1 FROM public.run_events e WHERE e.run_id=p_run AND e.terminal) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN;\n END IF;\n v_open:=openbot_internal.thread_history_lock_joint(v_r.thread_id,v_r.run_id);\n SELECT e.run_id,e.thread_id,e.event_type,e.seq\n  INTO v_e.run_id,v_e.thread_id,v_e.event_type,v_e.seq\n  FROM public.run_events e WHERE e.run_id=p_run AND e.terminal FOR SHARE OF e NOWAIT;\n v_event_found:=FOUND;\n IF v_r.status IN(''queued'',''running'') THEN\n  IF v_event_found THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n  RETURN;\n END IF;\n IF v_r.status NOT IN(''completed'',''failed'',''cancelled'',''reconciliation_required'') OR NOT v_event_found OR\n    ROW(v_r.run_id,v_r.thread_id,v_r.status,v_r.terminal_event_seq)\n     IS DISTINCT FROM ROW(v_e.run_id,v_e.thread_id,v_e.event_type,v_e.seq) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- Preserve the original open-J import contract: its verified bundle allows an\n -- arbitrary object terminal payload and valid historical error identifier. The\n -- fixed21-code payload is only the actual changed CLOSED terminal exception,\n -- not a new open import validator or revalidation of unchanged historical body.\n -- Nonterminal scrubs and terminal metadata do not read that historical payload.\n -- The final Run/event identity/status/sequence joint above is shared.\n IF v_open OR NOT p_terminal_changed THEN RETURN;END IF;\n SELECT e.payload INTO v_e.payload FROM public.run_events e\n  WHERE e.run_id=v_e.run_id AND e.seq=v_e.seq AND e.terminal FOR SHARE OF e NOWAIT;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n IF NOT openbot_internal.thread_history_terminal_payload(v_e.event_type,v_e.payload) OR\n    v_r.error_code IS DISTINCT FROM v_e.payload->>''errorCode'' THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_source","p_require_open"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_validate_channel_source(p_source openbot_internal.channel_history_sources, p_require_open boolean)\n RETURNS void\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_m public.messages%ROWTYPE;v_r public.runs%ROWTYPE;v_t public.threads%ROWTYPE;\n v_preview text;v_agent text;v_open boolean;\nBEGIN\n IF p_source.channel_id IS NULL OR p_require_open IS NULL THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- Caller/guard already holds the actual channel EXCLUSIVE row mutex.\n SELECT m.* INTO v_m FROM public.messages m\n  JOIN public.runs r ON r.run_id=m.run_id\n  JOIN public.threads t ON t.thread_id=r.thread_id AND t.thread_id=m.thread_id\n  WHERE m.message_id=p_source.message_id AND m.run_id=p_source.run_id\n    AND t.thread_id=p_source.thread_id AND t.anchor_kind=''channel''\n    AND t.anchor_id=p_source.channel_id FOR SHARE OF m,r,t NOWAIT;\n IF NOT FOUND THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n SELECT r.* INTO v_r FROM public.runs r WHERE r.run_id=v_m.run_id;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n SELECT t.* INTO v_t FROM public.threads t WHERE t.thread_id=v_m.thread_id;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n IF v_m.role=''user'' AND v_m.actor_id=v_r.actor_id THEN v_agent:=NULL;\n ELSIF v_m.role=''assistant'' AND v_m.actor_id IS NULL THEN v_agent:=v_r.bot_id;\n ELSE RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n IF pg_catalog.jsonb_typeof(v_m.content) IS DISTINCT FROM ''object'' OR\n    pg_catalog.jsonb_typeof(v_m.content->''text'') IS DISTINCT FROM ''string'' OR\n    v_m.content->>''text'' IS DISTINCT FROM v_m.search_text OR\n    ROW(p_source.source_schema,p_source.deployment_id,p_source.tenant_id,p_source.thread_id,\n        p_source.run_id,p_source.message_id,p_source.message_role,p_source.message_created_at,p_source.last_message_agent_id)\n       IS DISTINCT FROM ROW(1::smallint,v_t.deployment_id,v_t.tenant_id,v_t.thread_id,v_r.run_id,\n        v_m.message_id,v_m.role,v_m.created_at,v_agent) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_preview:=openbot_internal.thread_history_preview(v_m.search_text);\n IF p_source.preview_checksum IS DISTINCT FROM\n     pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_preview,''UTF8''::name)),''hex'') OR\n    p_source.preview_utf8_bytes IS DISTINCT FROM pg_catalog.octet_length(v_preview) OR\n    NOT pg_catalog.isfinite(p_source.message_created_at) OR NOT pg_catalog.isfinite(p_source.recorded_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_open:=openbot_internal.thread_history_lock_joint(v_t.thread_id,v_r.run_id);\n IF p_require_open AND NOT v_open THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_closed'';\n END IF;\nEND;\n$function$\n","identity":{"arguments":"p_source openbot_internal.channel_history_sources, p_require_open boolean","name":"thread_history_validate_channel_source","schema":"openbot_internal"},"inputArgumentCount":2,"inputTypes":[{"name":"channel_history_sources","ordinal":1,"schema":"openbot_internal"},{"name":"bool","ordinal":2,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"void","name":"void","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_m public.messages%ROWTYPE;v_r public.runs%ROWTYPE;v_t public.threads%ROWTYPE;\n v_preview text;v_agent text;v_open boolean;\nBEGIN\n IF p_source.channel_id IS NULL OR p_require_open IS NULL THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- Caller/guard already holds the actual channel EXCLUSIVE row mutex.\n SELECT m.* INTO v_m FROM public.messages m\n  JOIN public.runs r ON r.run_id=m.run_id\n  JOIN public.threads t ON t.thread_id=r.thread_id AND t.thread_id=m.thread_id\n  WHERE m.message_id=p_source.message_id AND m.run_id=p_source.run_id\n    AND t.thread_id=p_source.thread_id AND t.anchor_kind=''channel''\n    AND t.anchor_id=p_source.channel_id FOR SHARE OF m,r,t NOWAIT;\n IF NOT FOUND THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n SELECT r.* INTO v_r FROM public.runs r WHERE r.run_id=v_m.run_id;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n SELECT t.* INTO v_t FROM public.threads t WHERE t.thread_id=v_m.thread_id;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n IF v_m.role=''user'' AND v_m.actor_id=v_r.actor_id THEN v_agent:=NULL;\n ELSIF v_m.role=''assistant'' AND v_m.actor_id IS NULL THEN v_agent:=v_r.bot_id;\n ELSE RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n IF pg_catalog.jsonb_typeof(v_m.content) IS DISTINCT FROM ''object'' OR\n    pg_catalog.jsonb_typeof(v_m.content->''text'') IS DISTINCT FROM ''string'' OR\n    v_m.content->>''text'' IS DISTINCT FROM v_m.search_text OR\n    ROW(p_source.source_schema,p_source.deployment_id,p_source.tenant_id,p_source.thread_id,\n        p_source.run_id,p_source.message_id,p_source.message_role,p_source.message_created_at,p_source.last_message_agent_id)\n       IS DISTINCT FROM ROW(1::smallint,v_t.deployment_id,v_t.tenant_id,v_t.thread_id,v_r.run_id,\n        v_m.message_id,v_m.role,v_m.created_at,v_agent) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_preview:=openbot_internal.thread_history_preview(v_m.search_text);\n IF p_source.preview_checksum IS DISTINCT FROM\n     pg_catalog.encode(pg_catalog.sha256(pg_catalog.convert_to(v_preview,''UTF8''::name)),''hex'') OR\n    p_source.preview_utf8_bytes IS DISTINCT FROM pg_catalog.octet_length(v_preview) OR\n    NOT pg_catalog.isfinite(p_source.message_created_at) OR NOT pg_catalog.isfinite(p_source.recorded_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_open:=openbot_internal.thread_history_lock_joint(v_t.thread_id,v_r.run_id);\n IF p_require_open AND NOT v_open THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_closed'';\n END IF;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_table","p_old","p_new"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_related_channel_ids(p_table text, p_old jsonb, p_new jsonb)\n RETURNS text[]\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_threads text[];v_runs text[];v_messages text[];v_channels text[];v_result text[];\nBEGIN\n IF p_table NOT IN(''threads'',''runs'',''messages'',''channels'',''channel_history_sources'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_threads:=ARRAY[p_old->>''thread_id'',p_new->>''thread_id''];\n v_runs:=ARRAY[p_old->>''run_id'',p_new->>''run_id''];\n v_messages:=ARRAY[p_old->>''message_id'',p_new->>''message_id''];\n v_channels:=ARRAY[p_old->>''channel_id'',p_new->>''channel_id''];\n IF p_table=''channels'' THEN v_channels:=v_channels||ARRAY[p_old->>''id'',p_new->>''id''];END IF;\n IF p_table=''threads'' THEN\n  IF p_old->>''anchor_kind''=''channel'' THEN v_channels:=v_channels||(p_old->>''anchor_id'');END IF;\n  IF p_new->>''anchor_kind''=''channel'' THEN v_channels:=v_channels||(p_new->>''anchor_id'');END IF;\n END IF;\n SELECT pg_catalog.array_agg(z.id ORDER BY z.id COLLATE pg_catalog.\"C\") INTO v_result FROM (\n  SELECT DISTINCT id COLLATE pg_catalog.\"C\" AS id FROM (\n   SELECT x AS id FROM pg_catalog.unnest(v_channels) x WHERE x IS NOT NULL\n   UNION ALL SELECT t.anchor_id FROM public.threads t\n    WHERE t.anchor_kind=''channel'' AND (t.thread_id=ANY(v_threads)\n     OR EXISTS(SELECT 1 FROM public.runs r WHERE r.run_id=ANY(v_runs) AND r.thread_id=t.thread_id)\n     OR EXISTS(SELECT 1 FROM public.messages m WHERE m.message_id=ANY(v_messages) AND m.thread_id=t.thread_id))\n   UNION ALL SELECT s.channel_id FROM openbot_internal.channel_history_sources s\n    WHERE s.channel_id=ANY(v_channels) OR s.thread_id=ANY(v_threads)\n      OR s.run_id=ANY(v_runs) OR s.message_id=ANY(v_messages)\n  ) all_ids\n ) z;\n RETURN COALESCE(v_result,ARRAY[]::text[]);\nEND;\n$function$\n","identity":{"arguments":"p_table text, p_old jsonb, p_new jsonb","name":"thread_history_related_channel_ids","schema":"openbot_internal"},"inputArgumentCount":3,"inputTypes":[{"name":"text","ordinal":1,"schema":"pg_catalog"},{"name":"jsonb","ordinal":2,"schema":"pg_catalog"},{"name":"jsonb","ordinal":3,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"text[]","name":"_text","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_threads text[];v_runs text[];v_messages text[];v_channels text[];v_result text[];\nBEGIN\n IF p_table NOT IN(''threads'',''runs'',''messages'',''channels'',''channel_history_sources'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_threads:=ARRAY[p_old->>''thread_id'',p_new->>''thread_id''];\n v_runs:=ARRAY[p_old->>''run_id'',p_new->>''run_id''];\n v_messages:=ARRAY[p_old->>''message_id'',p_new->>''message_id''];\n v_channels:=ARRAY[p_old->>''channel_id'',p_new->>''channel_id''];\n IF p_table=''channels'' THEN v_channels:=v_channels||ARRAY[p_old->>''id'',p_new->>''id''];END IF;\n IF p_table=''threads'' THEN\n  IF p_old->>''anchor_kind''=''channel'' THEN v_channels:=v_channels||(p_old->>''anchor_id'');END IF;\n  IF p_new->>''anchor_kind''=''channel'' THEN v_channels:=v_channels||(p_new->>''anchor_id'');END IF;\n END IF;\n SELECT pg_catalog.array_agg(z.id ORDER BY z.id COLLATE pg_catalog.\"C\") INTO v_result FROM (\n  SELECT DISTINCT id COLLATE pg_catalog.\"C\" AS id FROM (\n   SELECT x AS id FROM pg_catalog.unnest(v_channels) x WHERE x IS NOT NULL\n   UNION ALL SELECT t.anchor_id FROM public.threads t\n    WHERE t.anchor_kind=''channel'' AND (t.thread_id=ANY(v_threads)\n     OR EXISTS(SELECT 1 FROM public.runs r WHERE r.run_id=ANY(v_runs) AND r.thread_id=t.thread_id)\n     OR EXISTS(SELECT 1 FROM public.messages m WHERE m.message_id=ANY(v_messages) AND m.thread_id=t.thread_id))\n   UNION ALL SELECT s.channel_id FROM openbot_internal.channel_history_sources s\n    WHERE s.channel_id=ANY(v_channels) OR s.thread_id=ANY(v_threads)\n      OR s.run_id=ANY(v_runs) OR s.message_id=ANY(v_messages)\n  ) all_ids\n ) z;\n RETURN COALESCE(v_result,ARRAY[]::text[]);\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_text"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_preview(p_text text)\n RETURNS text\n LANGUAGE plpgsql\n IMMUTABLE PARALLEL SAFE STRICT\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_char text; v_code integer; v_out text:=''''; v_gap boolean:=false;\n v_count integer:=0; v_i integer;\nBEGIN\n -- DB UTF8 was required before creating this function; no locale/POSIX class.\n FOR v_i IN 1..pg_catalog.length(p_text) LOOP\n  v_char:=pg_catalog.substr(p_text,v_i,1);v_code:=pg_catalog.ascii(v_char);\n  IF v_code<=31 OR v_code BETWEEN 127 AND 159 OR v_code=32 OR\n     v_code IN(160,5760,8232,8233,8239,8287,12288) OR\n     v_code BETWEEN 8192 AND 8202 THEN\n   IF v_count>0 THEN v_gap:=true; END IF;\n  ELSE\n   IF v_gap THEN v_out:=v_out||'' '';v_count:=v_count+1;v_gap:=false;END IF;\n   v_out:=v_out||v_char;v_count:=v_count+1;\n   -- All remaining characters are nonempty; >200 never shrinks again.\n   IF v_count>200 THEN RETURN pg_catalog.substr(v_out,1,199)||U&''\\2026''; END IF;\n  END IF;\n END LOOP;\n RETURN v_out;\nEND;\n$function$\n","identity":{"arguments":"p_text text","name":"thread_history_preview","schema":"openbot_internal"},"inputArgumentCount":1,"inputTypes":[{"name":"text","ordinal":1,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"s","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"text","name":"text","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_char text; v_code integer; v_out text:=''''; v_gap boolean:=false;\n v_count integer:=0; v_i integer;\nBEGIN\n -- DB UTF8 was required before creating this function; no locale/POSIX class.\n FOR v_i IN 1..pg_catalog.length(p_text) LOOP\n  v_char:=pg_catalog.substr(p_text,v_i,1);v_code:=pg_catalog.ascii(v_char);\n  IF v_code<=31 OR v_code BETWEEN 127 AND 159 OR v_code=32 OR\n     v_code IN(160,5760,8232,8233,8239,8287,12288) OR\n     v_code BETWEEN 8192 AND 8202 THEN\n   IF v_count>0 THEN v_gap:=true; END IF;\n  ELSE\n   IF v_gap THEN v_out:=v_out||'' '';v_count:=v_count+1;v_gap:=false;END IF;\n   v_out:=v_out||v_char;v_count:=v_count+1;\n   -- All remaining characters are nonempty; >200 never shrinks again.\n   IF v_count>200 THEN RETURN pg_catalog.substr(v_out,1,199)||U&''\\2026''; END IF;\n  END IF;\n END LOOP;\n RETURN v_out;\nEND;\n","sqlBody":null,"strict":true,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"i"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_thread","p_run"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_lock_joint(p_thread text, p_run text)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_t public.threads%ROWTYPE;\n v_h openbot_internal.thread_history_heads%ROWTYPE;\nBEGIN\n IF p_thread IS NULL THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF p_run IS NULL THEN\n  SELECT t.* INTO v_t FROM public.threads t WHERE t.thread_id=p_thread FOR SHARE OF t NOWAIT;\n ELSE\n  SELECT t.* INTO v_t FROM public.runs r JOIN public.threads t ON t.thread_id=r.thread_id\n   WHERE r.run_id=p_run AND t.thread_id=p_thread FOR SHARE OF r,t NOWAIT;\n END IF;\n IF NOT FOUND THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- The original caller''s bounded unique wait is allowed. The following separate\n -- volatile-function statement is a new RC snapshot; SERIALIZABLE stays unchanged.\n INSERT INTO openbot_internal.thread_history_heads\n  (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at)\n VALUES(v_t.deployment_id,v_t.tenant_id,v_t.thread_id,1,''open'',v_t.anchor_kind,v_t.anchor_id,v_t.created_at)\n ON CONFLICT(thread_id) DO NOTHING;\n SELECT h.* INTO v_h FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=p_thread FOR SHARE OF h NOWAIT;\n IF NOT FOUND OR v_h.head_schema IS DISTINCT FROM 1 OR\n    ROW(v_h.deployment_id,v_h.tenant_id,v_h.thread_id,v_h.anchor_kind,v_h.anchor_id,v_h.thread_created_at)\n       IS DISTINCT FROM ROW(v_t.deployment_id,v_t.tenant_id,v_t.thread_id,v_t.anchor_kind,v_t.anchor_id,v_t.created_at)\n    OR NOT pg_catalog.isfinite(v_t.created_at) OR NOT pg_catalog.isfinite(v_h.recorded_at) OR\n       v_t.anchor_kind NOT IN(''direct_bot'',''channel'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF v_h.phase=''open'' THEN\n  IF ROW(v_h.closure_operation_id,v_h.closure_request_id,v_h.closure_actor_id,\n         v_h.closure_auth_generation,v_h.closed_at) IS DISTINCT FROM ROW(NULL::text,NULL::text,NULL::text,NULL::bigint,NULL::timestamptz) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN true;\n ELSIF v_h.phase=''closed'' THEN\n  IF v_h.closure_operation_id IS NULL OR v_h.closure_request_id IS NULL OR v_h.closure_actor_id IS NULL OR\n     v_h.closure_auth_generation IS NULL OR v_h.closure_auth_generation<0 OR\n     v_h.closed_at IS NULL OR NOT pg_catalog.isfinite(v_h.closed_at) OR\n     pg_catalog.octet_length(v_h.closure_actor_id) NOT BETWEEN 1 AND 512 OR\n     v_h.closure_actor_id ~ U&''[\\0001-\\001F\\007F-\\009F]'' OR\n     v_h.closure_operation_id !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' OR\n     v_h.closure_request_id !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' OR\n     NOT EXISTS(SELECT 1 FROM openbot_internal.thread_history_clear_intents q\n       WHERE q.intent_schema=1 AND q.intent_kind=''stop_clear'' AND\n             ROW(q.deployment_id,q.tenant_id,q.thread_id,q.operation_id,q.request_id,q.actor_id,q.auth_generation,\n                 q.anchor_kind,q.anchor_id,q.thread_created_at,q.recorded_at)\n          IS NOT DISTINCT FROM ROW(v_h.deployment_id,v_h.tenant_id,v_h.thread_id,v_h.closure_operation_id,\n                 v_h.closure_request_id,v_h.closure_actor_id,v_h.closure_auth_generation,v_h.anchor_kind,\n                 v_h.anchor_id,v_h.thread_created_at,v_h.closed_at)) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN false;\n END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\nEND;\n$function$\n","identity":{"arguments":"p_thread text, p_run text","name":"thread_history_lock_joint","schema":"openbot_internal"},"inputArgumentCount":2,"inputTypes":[{"name":"text","ordinal":1,"schema":"pg_catalog"},{"name":"text","ordinal":2,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"boolean","name":"bool","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_t public.threads%ROWTYPE;\n v_h openbot_internal.thread_history_heads%ROWTYPE;\nBEGIN\n IF p_thread IS NULL THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF p_run IS NULL THEN\n  SELECT t.* INTO v_t FROM public.threads t WHERE t.thread_id=p_thread FOR SHARE OF t NOWAIT;\n ELSE\n  SELECT t.* INTO v_t FROM public.runs r JOIN public.threads t ON t.thread_id=r.thread_id\n   WHERE r.run_id=p_run AND t.thread_id=p_thread FOR SHARE OF r,t NOWAIT;\n END IF;\n IF NOT FOUND THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- The original caller''s bounded unique wait is allowed. The following separate\n -- volatile-function statement is a new RC snapshot; SERIALIZABLE stays unchanged.\n INSERT INTO openbot_internal.thread_history_heads\n  (deployment_id,tenant_id,thread_id,head_schema,phase,anchor_kind,anchor_id,thread_created_at)\n VALUES(v_t.deployment_id,v_t.tenant_id,v_t.thread_id,1,''open'',v_t.anchor_kind,v_t.anchor_id,v_t.created_at)\n ON CONFLICT(thread_id) DO NOTHING;\n SELECT h.* INTO v_h FROM openbot_internal.thread_history_heads h\n  WHERE h.thread_id=p_thread FOR SHARE OF h NOWAIT;\n IF NOT FOUND OR v_h.head_schema IS DISTINCT FROM 1 OR\n    ROW(v_h.deployment_id,v_h.tenant_id,v_h.thread_id,v_h.anchor_kind,v_h.anchor_id,v_h.thread_created_at)\n       IS DISTINCT FROM ROW(v_t.deployment_id,v_t.tenant_id,v_t.thread_id,v_t.anchor_kind,v_t.anchor_id,v_t.created_at)\n    OR NOT pg_catalog.isfinite(v_t.created_at) OR NOT pg_catalog.isfinite(v_h.recorded_at) OR\n       v_t.anchor_kind NOT IN(''direct_bot'',''channel'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF v_h.phase=''open'' THEN\n  IF ROW(v_h.closure_operation_id,v_h.closure_request_id,v_h.closure_actor_id,\n         v_h.closure_auth_generation,v_h.closed_at) IS DISTINCT FROM ROW(NULL::text,NULL::text,NULL::text,NULL::bigint,NULL::timestamptz) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN true;\n ELSIF v_h.phase=''closed'' THEN\n  IF v_h.closure_operation_id IS NULL OR v_h.closure_request_id IS NULL OR v_h.closure_actor_id IS NULL OR\n     v_h.closure_auth_generation IS NULL OR v_h.closure_auth_generation<0 OR\n     v_h.closed_at IS NULL OR NOT pg_catalog.isfinite(v_h.closed_at) OR\n     pg_catalog.octet_length(v_h.closure_actor_id) NOT BETWEEN 1 AND 512 OR\n     v_h.closure_actor_id ~ U&''[\\0001-\\001F\\007F-\\009F]'' OR\n     v_h.closure_operation_id !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' OR\n     v_h.closure_request_id !~ ''^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'' OR\n     NOT EXISTS(SELECT 1 FROM openbot_internal.thread_history_clear_intents q\n       WHERE q.intent_schema=1 AND q.intent_kind=''stop_clear'' AND\n             ROW(q.deployment_id,q.tenant_id,q.thread_id,q.operation_id,q.request_id,q.actor_id,q.auth_generation,\n                 q.anchor_kind,q.anchor_id,q.thread_created_at,q.recorded_at)\n          IS NOT DISTINCT FROM ROW(v_h.deployment_id,v_h.tenant_id,v_h.thread_id,v_h.closure_operation_id,\n                 v_h.closure_request_id,v_h.closure_actor_id,v_h.closure_auth_generation,v_h.anchor_kind,\n                 v_h.anchor_id,v_h.thread_created_at,v_h.closed_at)) THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN false;\n END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":["p_type","p_payload"],"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.thread_history_terminal_payload(p_type text, p_payload jsonb)\n RETURNS boolean\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nBEGIN\n IF p_type IN(''completed'',''cancelled'') THEN\n  RETURN p_payload IS NOT DISTINCT FROM pg_catalog.jsonb_build_object(''status'',p_type);\n ELSIF p_type IN(''failed'',''reconciliation_required'') THEN\n  RETURN COALESCE(p_payload->>''errorCode''=ANY(ARRAY[\n   ''agent_runtime_unavailable'',''runtime_lease_expired'',''dispatch_payload_corrupt'',''dispatch_dead_letter'',\n   ''provider_authentication'',''provider_rate_limited'',''provider_unavailable'',''provider_commit_unknown'',\n   ''provider_invalid_response'',''agent_stream_stalled'',''provider_generation_failed'',''provider_token_budget_exceeded'',\n   ''run_token_budget_exceeded'',''run_cost_budget_unpriced'',''run_cost_budget_currency_mismatch'',''run_cost_budget_exceeded'',\n   ''tool_step_limit'',''tool_loop_unavailable'',''tool_denied'',''run_deadline_exceeded'',''journal_commit_unknown'']::text[]),false)\n   AND p_payload IS NOT DISTINCT FROM\n    pg_catalog.jsonb_build_object(''status'',p_type,''errorCode'',p_payload->>''errorCode'');\n END IF;\n RETURN false;\nEND;\n$function$\n","identity":{"arguments":"p_type text, p_payload jsonb","name":"thread_history_terminal_payload","schema":"openbot_internal"},"inputArgumentCount":2,"inputTypes":[{"name":"text","ordinal":1,"schema":"pg_catalog"},{"name":"jsonb","ordinal":2,"schema":"pg_catalog"}],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"boolean","name":"bool","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nBEGIN\n IF p_type IN(''completed'',''cancelled'') THEN\n  RETURN p_payload IS NOT DISTINCT FROM pg_catalog.jsonb_build_object(''status'',p_type);\n ELSIF p_type IN(''failed'',''reconciliation_required'') THEN\n  RETURN COALESCE(p_payload->>''errorCode''=ANY(ARRAY[\n   ''agent_runtime_unavailable'',''runtime_lease_expired'',''dispatch_payload_corrupt'',''dispatch_dead_letter'',\n   ''provider_authentication'',''provider_rate_limited'',''provider_unavailable'',''provider_commit_unknown'',\n   ''provider_invalid_response'',''agent_stream_stalled'',''provider_generation_failed'',''provider_token_budget_exceeded'',\n   ''run_token_budget_exceeded'',''run_cost_budget_unpriced'',''run_cost_budget_currency_mismatch'',''run_cost_budget_exceeded'',\n   ''tool_step_limit'',''tool_loop_unavailable'',''tool_denied'',''run_deadline_exceeded'',''journal_commit_unknown'']::text[]),false)\n   AND p_payload IS NOT DISTINCT FROM\n    pg_catalog.jsonb_build_object(''status'',p_type,''errorCode'',p_payload->>''errorCode'');\n END IF;\n RETURN false;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.guard_channel_history_source()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_ids text[];v_at timestamptz;v_old jsonb;v_new jsonb;\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''channel_history_sources''\n    OR TG_OP NOT IN(''INSERT'',''UPDATE'',''DELETE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF TG_OP<>''INSERT'' THEN v_old:=pg_catalog.to_jsonb(OLD);END IF;\n IF TG_OP<>''DELETE'' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;\n v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);\n PERFORM openbot_internal.thread_history_lock_channel_ids(v_ids);\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;\n IF TG_OP=''UPDATE'' AND (v_old-''recorded_at'') IS NOT DISTINCT FROM (v_new-''recorded_at'') THEN\n  IF NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_source_mutation_refused'';\n  END IF;\n  RETURN NEW;\n END IF;\n SELECT c.last_message_at INTO v_at FROM public.channels c WHERE c.id=NEW.channel_id;\n IF NOT FOUND OR (v_at IS NOT NULL AND NOT v_at<NEW.message_created_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_source_order_refused'';\n END IF;\n NEW.recorded_at:=pg_catalog.clock_timestamp();\n PERFORM openbot_internal.thread_history_validate_channel_source(NEW,true);\n RETURN NEW;\nEND;\n$function$\n","identity":{"arguments":"","name":"guard_channel_history_source","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_ids text[];v_at timestamptz;v_old jsonb;v_new jsonb;\nBEGIN\n IF TG_TABLE_SCHEMA<>''openbot_internal'' OR TG_TABLE_NAME<>''channel_history_sources''\n    OR TG_OP NOT IN(''INSERT'',''UPDATE'',''DELETE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF TG_OP<>''INSERT'' THEN v_old:=pg_catalog.to_jsonb(OLD);END IF;\n IF TG_OP<>''DELETE'' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;\n v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);\n PERFORM openbot_internal.thread_history_lock_channel_ids(v_ids);\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;\n IF TG_OP=''UPDATE'' AND (v_old-''recorded_at'') IS NOT DISTINCT FROM (v_new-''recorded_at'') THEN\n  IF NEW.recorded_at IS DISTINCT FROM OLD.recorded_at THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_source_mutation_refused'';\n  END IF;\n  RETURN NEW;\n END IF;\n SELECT c.last_message_at INTO v_at FROM public.channels c WHERE c.id=NEW.channel_id;\n IF NOT FOUND OR (v_at IS NOT NULL AND NOT v_at<NEW.message_created_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_source_order_refused'';\n END IF;\n NEW.recorded_at:=pg_catalog.clock_timestamp();\n PERFORM openbot_internal.thread_history_validate_channel_source(NEW,true);\n RETURN NEW;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.guard_thread_history_body()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_old jsonb;v_new jsonb;v_sources text[];v_bodies text[];v_key text;\n v_source_changed boolean:=false;v_body_changed boolean:=false;\n v_scrub boolean:=false;v_old_open boolean:=true;v_new_open boolean;\n v_row jsonb;v_rows jsonb[];v_run text;v_namespace_match boolean;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME NOT IN(''threads'',''runs'',''messages'',''run_events'',\n    ''tool_approvals'',''component_human_decisions'',''remote_agent_interrupts'') OR\n    TG_OP NOT IN(''INSERT'',''UPDATE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_new:=pg_catalog.to_jsonb(NEW);\n IF TG_OP=''UPDATE'' THEN v_old:=pg_catalog.to_jsonb(OLD);END IF;\n CASE TG_TABLE_NAME\n WHEN ''threads'' THEN\n  v_sources:=ARRAY[''thread_id'',''tenant_id'',''deployment_id'',''anchor_kind'',''anchor_id'',''created_at''];\n  v_bodies:=ARRAY[''title''];\n WHEN ''runs'' THEN\n  v_sources:=ARRAY[''run_id'',''thread_id'',''bot_id'',''actor_id''];v_bodies:=ARRAY[]::text[];\n WHEN ''messages'' THEN\n  v_sources:=ARRAY[''message_id'',''thread_id'',''run_id'',''role'',''actor_id'',''created_at''];\n  v_bodies:=ARRAY[''content'',''search_text''];\n WHEN ''run_events'' THEN\n  v_sources:=ARRAY[''run_id'',''thread_id'',''seq'',''event_seq'',''event_type'',''terminal'',''created_at''];\n  v_bodies:=ARRAY[''payload''];\n WHEN ''tool_approvals'' THEN\n  v_sources:=ARRAY[''approval_id'',''deployment_id'',''tenant_id'',''thread_id'',''run_id'',''actor_id'',''bot_id''];\n  v_bodies:=ARRAY[''arguments_summary'',''change_summary''];\n WHEN ''component_human_decisions'' THEN\n  v_sources:=ARRAY[''decision_id'',''deployment_id'',''tenant_id'',''thread_id'',''run_id'',''actor_id'',''bot_id''];\n  v_bodies:=ARRAY[''arguments'',''answer''];\n WHEN ''remote_agent_interrupts'' THEN\n  v_sources:=ARRAY[''request_id'',''deployment_id'',''tenant_id'',''thread_id'',''run_id'',''actor_id'',''bot_id''];\n  v_bodies:=ARRAY[''descriptor'',''response_payload''];\n END CASE;\n IF TG_OP=''UPDATE'' THEN\n  FOREACH v_key IN ARRAY v_sources LOOP\n   IF (v_old->v_key) IS DISTINCT FROM (v_new->v_key) THEN v_source_changed:=true;END IF;\n  END LOOP;\n  FOREACH v_key IN ARRAY v_bodies LOOP\n   IF (v_old->v_key) IS DISTINCT FROM (v_new->v_key) THEN v_body_changed:=true;END IF;\n  END LOOP;\n  IF NOT v_source_changed AND NOT v_body_changed THEN RETURN NEW;END IF;\n END IF;\n -- Thread INSERT runs AFTER physical insertion; newRun checks its existing Thread\n -- with p_run=NULL rather than querying nonexistent NEW Run. Run UPDATE''s OLD\n -- actual Run joint is checked, while its NEW referenced Thread is checked directly.\n IF TG_OP=''UPDATE'' THEN\n  v_run:=CASE WHEN TG_TABLE_NAME=''threads'' THEN NULL ELSE v_old->>''run_id'' END;\n  v_old_open:=openbot_internal.thread_history_lock_joint(v_old->>''thread_id'',v_run);\n END IF;\n v_run:=CASE WHEN TG_TABLE_NAME IN(''threads'',''runs'') THEN NULL ELSE v_new->>''run_id'' END;\n v_new_open:=openbot_internal.thread_history_lock_joint(v_new->>''thread_id'',v_run);\n IF TG_TABLE_NAME IN(''tool_approvals'',''component_human_decisions'',''remote_agent_interrupts'') THEN\n  v_rows:=CASE WHEN TG_OP=''UPDATE'' THEN ARRAY[v_old,v_new] ELSE ARRAY[v_new] END;\n  FOREACH v_row IN ARRAY v_rows LOOP\n   SELECT true INTO v_namespace_match FROM public.runs r JOIN public.threads t ON t.thread_id=r.thread_id\n    WHERE r.run_id=v_row->>''run_id'' AND t.thread_id=v_row->>''thread_id''\n      AND ROW(t.deployment_id,t.tenant_id,r.actor_id,r.bot_id) IS NOT DISTINCT FROM\n       ROW(v_row->>''deployment_id'',v_row->>''tenant_id'',v_row->>''actor_id'',v_row->>''bot_id'')\n    FOR SHARE OF r,t NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n  END LOOP;\n END IF;\n IF v_old_open AND v_new_open THEN RETURN NEW;END IF;\n -- Every OLD/NEW source migration requires both actual source J states open.\n IF TG_OP=''UPDATE'' AND v_source_changed THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_closed'';\n END IF;\n IF TG_TABLE_NAME=''run_events'' THEN\n  IF NEW.terminal AND openbot_internal.thread_history_terminal_payload(NEW.event_type,NEW.payload) THEN\n   RETURN NEW;\n  END IF;\n END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF TG_TABLE_NAME IN(''threads'',''tool_approvals'',''remote_agent_interrupts'') THEN\n   v_scrub:=true;\n   FOREACH v_key IN ARRAY v_bodies LOOP\n    IF (v_old->v_key) IS DISTINCT FROM (v_new->v_key) AND\n       (v_new->v_key) IS DISTINCT FROM ''null''::jsonb THEN v_scrub:=false;END IF;\n   END LOOP;\n  ELSIF TG_TABLE_NAME=''component_human_decisions'' THEN\n   v_scrub:=(v_old->''arguments'') IS NOT DISTINCT FROM (v_new->''arguments'')\n     AND NEW.answer IS NULL;\n  ELSIF TG_TABLE_NAME=''run_events'' THEN\n   v_scrub:=(OLD.event_type=''semantic_chunk'' AND OLD.payload->>''channel''=''reasoning''\n       AND NEW.payload=''{\"channel\":\"reasoning\",\"delta\":\"\",\"retained\":false}''::jsonb)\n     OR (OLD.event_type=''checkpoint'' AND OLD.payload->>''kind''=''remote_agui_projection''\n       AND OLD.payload->>''source''=''remote_ag_ui''\n       AND NEW.payload=''{\"kind\":\"remote_agui_projection\",\"source\":\"remote_ag_ui\",\"retained\":false,\"untrusted\":true}''::jsonb);\n  END IF;\n END IF;\n IF v_scrub THEN RETURN NEW;END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_closed'';\nEND;\n$function$\n","identity":{"arguments":"","name":"guard_thread_history_body","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_old jsonb;v_new jsonb;v_sources text[];v_bodies text[];v_key text;\n v_source_changed boolean:=false;v_body_changed boolean:=false;\n v_scrub boolean:=false;v_old_open boolean:=true;v_new_open boolean;\n v_row jsonb;v_rows jsonb[];v_run text;v_namespace_match boolean;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME NOT IN(''threads'',''runs'',''messages'',''run_events'',\n    ''tool_approvals'',''component_human_decisions'',''remote_agent_interrupts'') OR\n    TG_OP NOT IN(''INSERT'',''UPDATE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n v_new:=pg_catalog.to_jsonb(NEW);\n IF TG_OP=''UPDATE'' THEN v_old:=pg_catalog.to_jsonb(OLD);END IF;\n CASE TG_TABLE_NAME\n WHEN ''threads'' THEN\n  v_sources:=ARRAY[''thread_id'',''tenant_id'',''deployment_id'',''anchor_kind'',''anchor_id'',''created_at''];\n  v_bodies:=ARRAY[''title''];\n WHEN ''runs'' THEN\n  v_sources:=ARRAY[''run_id'',''thread_id'',''bot_id'',''actor_id''];v_bodies:=ARRAY[]::text[];\n WHEN ''messages'' THEN\n  v_sources:=ARRAY[''message_id'',''thread_id'',''run_id'',''role'',''actor_id'',''created_at''];\n  v_bodies:=ARRAY[''content'',''search_text''];\n WHEN ''run_events'' THEN\n  v_sources:=ARRAY[''run_id'',''thread_id'',''seq'',''event_seq'',''event_type'',''terminal'',''created_at''];\n  v_bodies:=ARRAY[''payload''];\n WHEN ''tool_approvals'' THEN\n  v_sources:=ARRAY[''approval_id'',''deployment_id'',''tenant_id'',''thread_id'',''run_id'',''actor_id'',''bot_id''];\n  v_bodies:=ARRAY[''arguments_summary'',''change_summary''];\n WHEN ''component_human_decisions'' THEN\n  v_sources:=ARRAY[''decision_id'',''deployment_id'',''tenant_id'',''thread_id'',''run_id'',''actor_id'',''bot_id''];\n  v_bodies:=ARRAY[''arguments'',''answer''];\n WHEN ''remote_agent_interrupts'' THEN\n  v_sources:=ARRAY[''request_id'',''deployment_id'',''tenant_id'',''thread_id'',''run_id'',''actor_id'',''bot_id''];\n  v_bodies:=ARRAY[''descriptor'',''response_payload''];\n END CASE;\n IF TG_OP=''UPDATE'' THEN\n  FOREACH v_key IN ARRAY v_sources LOOP\n   IF (v_old->v_key) IS DISTINCT FROM (v_new->v_key) THEN v_source_changed:=true;END IF;\n  END LOOP;\n  FOREACH v_key IN ARRAY v_bodies LOOP\n   IF (v_old->v_key) IS DISTINCT FROM (v_new->v_key) THEN v_body_changed:=true;END IF;\n  END LOOP;\n  IF NOT v_source_changed AND NOT v_body_changed THEN RETURN NEW;END IF;\n END IF;\n -- Thread INSERT runs AFTER physical insertion; newRun checks its existing Thread\n -- with p_run=NULL rather than querying nonexistent NEW Run. Run UPDATE''s OLD\n -- actual Run joint is checked, while its NEW referenced Thread is checked directly.\n IF TG_OP=''UPDATE'' THEN\n  v_run:=CASE WHEN TG_TABLE_NAME=''threads'' THEN NULL ELSE v_old->>''run_id'' END;\n  v_old_open:=openbot_internal.thread_history_lock_joint(v_old->>''thread_id'',v_run);\n END IF;\n v_run:=CASE WHEN TG_TABLE_NAME IN(''threads'',''runs'') THEN NULL ELSE v_new->>''run_id'' END;\n v_new_open:=openbot_internal.thread_history_lock_joint(v_new->>''thread_id'',v_run);\n IF TG_TABLE_NAME IN(''tool_approvals'',''component_human_decisions'',''remote_agent_interrupts'') THEN\n  v_rows:=CASE WHEN TG_OP=''UPDATE'' THEN ARRAY[v_old,v_new] ELSE ARRAY[v_new] END;\n  FOREACH v_row IN ARRAY v_rows LOOP\n   SELECT true INTO v_namespace_match FROM public.runs r JOIN public.threads t ON t.thread_id=r.thread_id\n    WHERE r.run_id=v_row->>''run_id'' AND t.thread_id=v_row->>''thread_id''\n      AND ROW(t.deployment_id,t.tenant_id,r.actor_id,r.bot_id) IS NOT DISTINCT FROM\n       ROW(v_row->>''deployment_id'',v_row->>''tenant_id'',v_row->>''actor_id'',v_row->>''bot_id'')\n    FOR SHARE OF r,t NOWAIT;\n   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n  END LOOP;\n END IF;\n IF v_old_open AND v_new_open THEN RETURN NEW;END IF;\n -- Every OLD/NEW source migration requires both actual source J states open.\n IF TG_OP=''UPDATE'' AND v_source_changed THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_closed'';\n END IF;\n IF TG_TABLE_NAME=''run_events'' THEN\n  IF NEW.terminal AND openbot_internal.thread_history_terminal_payload(NEW.event_type,NEW.payload) THEN\n   RETURN NEW;\n  END IF;\n END IF;\n IF TG_OP=''UPDATE'' THEN\n  IF TG_TABLE_NAME IN(''threads'',''tool_approvals'',''remote_agent_interrupts'') THEN\n   v_scrub:=true;\n   FOREACH v_key IN ARRAY v_bodies LOOP\n    IF (v_old->v_key) IS DISTINCT FROM (v_new->v_key) AND\n       (v_new->v_key) IS DISTINCT FROM ''null''::jsonb THEN v_scrub:=false;END IF;\n   END LOOP;\n  ELSIF TG_TABLE_NAME=''component_human_decisions'' THEN\n   v_scrub:=(v_old->''arguments'') IS NOT DISTINCT FROM (v_new->''arguments'')\n     AND NEW.answer IS NULL;\n  ELSIF TG_TABLE_NAME=''run_events'' THEN\n   v_scrub:=(OLD.event_type=''semantic_chunk'' AND OLD.payload->>''channel''=''reasoning''\n       AND NEW.payload=''{\"channel\":\"reasoning\",\"delta\":\"\",\"retained\":false}''::jsonb)\n     OR (OLD.event_type=''checkpoint'' AND OLD.payload->>''kind''=''remote_agui_projection''\n       AND OLD.payload->>''source''=''remote_ag_ui''\n       AND NEW.payload=''{\"kind\":\"remote_agui_projection\",\"source\":\"remote_ag_ui\",\"retained\":false,\"untrusted\":true}''::jsonb);\n  END IF;\n END IF;\n IF v_scrub THEN RETURN NEW;END IF;\n RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_closed'';\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.guard_thread_history_canonical_reverse()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_ids text[];v_old jsonb;v_new jsonb;v_keys text[];v_changed boolean;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME NOT IN(''messages'',''runs'',''threads'') OR\n    TG_OP NOT IN(''UPDATE'',''DELETE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- Original target DML has already acquired its canonical row lock. Thus all\n -- newly added channel locks are NOWAIT; no hidden reverse wait order is assumed.\n v_old:=pg_catalog.to_jsonb(OLD);\n IF TG_OP=''UPDATE'' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;\n v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);\n PERFORM openbot_internal.thread_history_lock_channel_ids(v_ids);\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;\n -- A preview hash does not fingerprint the entire canonical body or every Run\n -- identity. A final preview comparison alone would miss a change after codepoint\n -- 200 or an assistant Run.actor change. Require the source pointer to be cleared\n -- or moved in this same Tx BEFORE an actual referenced canonical UPDATE. The\n -- subsequent deferred check still verifies the final replacement/NULL relation.\n IF TG_TABLE_NAME=''messages'' THEN\n  v_keys:=ARRAY[''message_id'',''thread_id'',''run_id'',''role'',''actor_id'',''created_at'',''content'',''search_text''];\n ELSIF TG_TABLE_NAME=''runs'' THEN\n  v_keys:=ARRAY[''run_id'',''thread_id'',''actor_id'',''bot_id''];\n ELSE\n  v_keys:=ARRAY[''thread_id'',''tenant_id'',''deployment_id'',''anchor_kind'',''anchor_id'',''created_at''];\n END IF;\n SELECT pg_catalog.bool_or(v_old->k IS DISTINCT FROM v_new->k) INTO v_changed\n  FROM pg_catalog.unnest(v_keys) k;\n IF v_changed AND EXISTS(SELECT 1 FROM openbot_internal.channel_history_sources s\n    WHERE (TG_TABLE_NAME=''messages'' AND s.message_id=ANY(ARRAY[v_old->>''message_id'',v_new->>''message_id'']))\n       OR (TG_TABLE_NAME=''runs'' AND s.run_id=ANY(ARRAY[v_old->>''run_id'',v_new->>''run_id'']))\n       OR (TG_TABLE_NAME=''threads'' AND s.thread_id=ANY(ARRAY[v_old->>''thread_id'',v_new->>''thread_id'']))) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_source_mutation_refused'';\n END IF;\n RETURN NEW;\nEND;\n$function$\n","identity":{"arguments":"","name":"guard_thread_history_canonical_reverse","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_ids text[];v_old jsonb;v_new jsonb;v_keys text[];v_changed boolean;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME NOT IN(''messages'',''runs'',''threads'') OR\n    TG_OP NOT IN(''UPDATE'',''DELETE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n -- Original target DML has already acquired its canonical row lock. Thus all\n -- newly added channel locks are NOWAIT; no hidden reverse wait order is assumed.\n v_old:=pg_catalog.to_jsonb(OLD);\n IF TG_OP=''UPDATE'' THEN v_new:=pg_catalog.to_jsonb(NEW);END IF;\n v_ids:=openbot_internal.thread_history_related_channel_ids(TG_TABLE_NAME,v_old,v_new);\n PERFORM openbot_internal.thread_history_lock_channel_ids(v_ids);\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;\n -- A preview hash does not fingerprint the entire canonical body or every Run\n -- identity. A final preview comparison alone would miss a change after codepoint\n -- 200 or an assistant Run.actor change. Require the source pointer to be cleared\n -- or moved in this same Tx BEFORE an actual referenced canonical UPDATE. The\n -- subsequent deferred check still verifies the final replacement/NULL relation.\n IF TG_TABLE_NAME=''messages'' THEN\n  v_keys:=ARRAY[''message_id'',''thread_id'',''run_id'',''role'',''actor_id'',''created_at'',''content'',''search_text''];\n ELSIF TG_TABLE_NAME=''runs'' THEN\n  v_keys:=ARRAY[''run_id'',''thread_id'',''actor_id'',''bot_id''];\n ELSE\n  v_keys:=ARRAY[''thread_id'',''tenant_id'',''deployment_id'',''anchor_kind'',''anchor_id'',''created_at''];\n END IF;\n SELECT pg_catalog.bool_or(v_old->k IS DISTINCT FROM v_new->k) INTO v_changed\n  FROM pg_catalog.unnest(v_keys) k;\n IF v_changed AND EXISTS(SELECT 1 FROM openbot_internal.channel_history_sources s\n    WHERE (TG_TABLE_NAME=''messages'' AND s.message_id=ANY(ARRAY[v_old->>''message_id'',v_new->>''message_id'']))\n       OR (TG_TABLE_NAME=''runs'' AND s.run_id=ANY(ARRAY[v_old->>''run_id'',v_new->>''run_id'']))\n       OR (TG_TABLE_NAME=''threads'' AND s.thread_id=ANY(ARRAY[v_old->>''thread_id'',v_new->>''thread_id'']))) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_source_mutation_refused'';\n END IF;\n RETURN NEW;\nEND;\n","sqlBody":null,"strict":false,"supportFunction":null,"transformTypes":[],"transformTypesIsNull":true,"variadicType":null,"volatility":"v"},{"acl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"aclIsNull":false,"allArgumentTypes":[],"allArgumentTypesIsNull":true,"argumentDefaults":null,"argumentModes":null,"argumentNames":null,"binary":null,"configuration":["search_path=pg_catalog, openbot_internal"],"cost":100,"defaultArgumentCount":0,"definition":"CREATE OR REPLACE FUNCTION openbot_internal.guard_thread_history_channel_projection()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO ''pg_catalog'', ''openbot_internal''\nAS $function$\nDECLARE v_s openbot_internal.channel_history_sources%ROWTYPE;v_preview text;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''channels'' OR TG_OP NOT IN(''INSERT'',''UPDATE'',''DELETE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF TG_OP=''INSERT'' THEN\n  -- A source cannot reference an uninserted channel: insert empty, then source+preview.\n  IF NEW.last_message IS NOT NULL OR NEW.last_message_at IS NOT NULL OR NEW.last_message_agent_id IS NOT NULL THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN NEW;\n END IF;\n PERFORM openbot_internal.thread_history_lock_channel_ids(ARRAY[OLD.id]);\n IF TG_OP=''DELETE'' THEN RETURN OLD;END IF;\n IF ROW(NEW.last_message,NEW.last_message_at,NEW.last_message_agent_id) IS NOT DISTINCT FROM\n    ROW(OLD.last_message,OLD.last_message_at,OLD.last_message_agent_id) THEN\n  RETURN NEW;\n END IF;\n IF NEW.last_message IS NULL THEN\n  IF NEW.last_message_at IS NOT NULL OR NEW.last_message_agent_id IS NOT NULL THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN NEW;\n END IF;\n -- Source must be already written for this actual channel identity.\n SELECT s.* INTO v_s FROM openbot_internal.channel_history_sources s WHERE s.channel_id=NEW.id;\n IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';END IF;\n PERFORM openbot_internal.thread_history_validate_channel_source(v_s,true);\n SELECT openbot_internal.thread_history_preview(m.search_text) INTO v_preview\n  FROM public.messages m WHERE m.message_id=v_s.message_id;\n IF NOT FOUND OR ROW(NEW.last_message,NEW.last_message_at,NEW.last_message_agent_id)\n    IS DISTINCT FROM ROW(v_preview,v_s.message_created_at,v_s.last_message_agent_id) OR\n    (OLD.last_message_at IS NOT NULL AND NOT OLD.last_message_at<NEW.last_message_at) THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n RETURN NEW;\nEND;\n$function$\n","identity":{"arguments":"","name":"guard_thread_history_channel_projection","schema":"openbot_internal"},"inputArgumentCount":0,"inputTypes":[],"isSyncFunction":false,"kind":"f","language":"plpgsql","leakproof":false,"ownerRef":"original_threads_owner","parallel":"u","rawAcl":[{"grantable":false,"grantee":"original_threads_owner","grantor":"original_threads_owner","privilege":"EXECUTE"}],"returnType":{"formatted":"trigger","name":"trigger","schema":"pg_catalog"},"rows":0,"securityDefiner":false,"setReturning":false,"source":"\nDECLARE v_s openbot_internal.channel_history_sources%ROWTYPE;v_preview text;\nBEGIN\n IF TG_TABLE_SCHEMA<>''public'' OR TG_TABLE_NAME<>''channels'' OR TG_OP NOT IN(''INSERT'',''UPDATE'',''DELETE'') THEN\n  RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n END IF;\n IF TG_OP=''INSERT'' THEN\n  -- A source cannot reference an uninserted channel: insert empty, then source+preview.\n  IF NEW.last_message IS NOT NULL OR NEW.last_message_at IS NOT NULL OR NEW.last_message_agent_id IS NOT NULL THEN\n   RAISE EXCEPTION USING ERRCODE=''55000'',MESSAGE=''thread_history_writer_binding_invalid'';\n  END IF;\n  RETURN NEW;\n END IF;\n PERFORM openbot_internal.thread_history_lock_channel_ids(ARRAY[OLD.id]);\n IF 