  'sourceToast',pg_catalog.jsonb_build_object(
   'relation',(SELECT pg_catalog.to_jsonb(t) FROM source_toast t),
   'indexes',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('class',pg_catalog.to_jsonb(c),'index',pg_catalog.to_jsonb(i)||pg_catalog.jsonb_build_object('indkey',pg_catalog.to_jsonb(i.indkey::smallint[]),'indclass',pg_catalog.to_jsonb(i.indclass::pg_catalog.oid[]),'indcollation',pg_catalog.to_jsonb(i.indcollation::pg_catalog.oid[]),'indoption',pg_catalog.to_jsonb(i.indoption::smallint[]))) ORDER BY i.indexrelid),'[]'::jsonb) FROM source_toast_indexes i JOIN pg_catalog.pg_class c ON c.oid=i.indexrelid),
