   'operatorClasses',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('class',pg_catalog.to_jsonb(o),'family',pg_catalog.to_jsonb(f),'method',pg_catalog.to_jsonb(m)||pg_catalog.jsonb_build_object('amhandler',m.amhandler::oid)) ORDER BY o.oid),'[]'::jsonb)
    FROM pg_catalog.pg_opclass o JOIN pg_catalog.pg_opfamily f ON f.oid=o.opcfamily JOIN pg_catalog.pg_am m ON m.oid=o.opcmethod
    WHERE o.oid IN (SELECT pg_catalog.unnest(i.indclass::pg_catalog.oid[]) FROM source_toast_indexes i))),
  'newFunctionLanguages',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('oid',p.oid,'prolang',p.prolang) ORDER BY p.oid),'[]'::jsonb) FROM new_functions p),
  'plpgsql',(SELECT pg_catalog.to_jsonb(l)||pg_catalog.jsonb_build_object('lanplcallfoid',l.lanplcallfoid::oid,'laninline',l.laninline::oid,'lanvalidator',l.lanvalidator::oid) FROM pg_catalog.pg_language l WHERE l.lanname='plpgsql'),
  'languageContract',pg_catalog.jsonb_build_object(
