   'functions',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p)||pg_catalog.jsonb_build_object('proargtypes',pg_catalog.to_jsonb(p.proargtypes::pg_catalog.oid[]),'prosupport',p.prosupport::oid) ORDER BY p.oid),'[]'::jsonb)
    FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='pg_catalog' AND p.proname IN ('plpgsql_call_handler','plpgsql_inline_handler','plpgsql_validator')),
   'languageEffectiveAcl',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('grantor',a.grantor,'grantee',a.grantee,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY a.grantor,a.grantee,a.privilege_type COLLATE pg_catalog."C",a.is_grantable),'[]'::jsonb)
    FROM pg_catalog.pg_language l CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(l.lanacl,pg_catalog.acldefault('l'::pg_catalog."char",l.lanowner))) a WHERE l.lanname='plpgsql'),
   'functionEffectiveAcls',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name',p.proname,'acl',(
