  'accessMethods',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p)||pg_catalog.jsonb_build_object('amhandler',p.amhandler::oid) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_am p WHERE p.oid IN(SELECT(x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements((v_expected->'rawContract')->'accessMethods')x)),
  'toastOperatorClasses',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_opclass p WHERE p.oid IN(SELECT(x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements((v_expected->'rawContract')->'toastOperatorClasses')x)),
  'toastOperatorFamilies',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_opfamily p WHERE p.oid IN(SELECT(x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements((v_expected->'rawContract')->'toastOperatorFamilies')x)),
  'collations',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p) ORDER BY p.oid),'[]'::jsonb) FROM pg_catalog.pg_collation p WHERE p.oid IN(SELECT(x->>'oid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements((v_expected->'rawContract')->'collations')x)),
  'aggregates',(SELECT coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(p)||pg_catalog.jsonb_build_object('aggfnoid',p.aggfnoid::oid,'aggtransfn',p.aggtransfn::oid,'aggfinalfn',p.aggfinalfn::oid,'aggcombinefn',p.aggcombinefn::oid,'aggserialfn',p.aggserialfn::oid,'aggdeserialfn',p.aggdeserialfn::oid,'aggmtransfn',p.aggmtransfn::oid,'aggminvtransfn',p.aggminvtransfn::oid,'aggmfinalfn',p.aggmfinalfn::oid) ORDER BY p.aggfnoid),'[]'::jsonb)
    FROM pg_catalog.pg_aggregate p WHERE p.aggfnoid IN (SELECT (x->>'aggfnoid')::pg_catalog.oid FROM pg_catalog.jsonb_array_elements((v_expected->'rawContract')->'aggregates') x))),
 'relations',(SELECT coalesce(pg_catalog.jsonb_agg(f.facts ORDER BY f.schema_name COLLATE pg_catalog."C",f.relname COLLATE pg_catalog."C"),'[]'::jsonb) FROM relation_facts f),
 'constraints',(SELECT coalesce(pg_catalog.jsonb_agg(f.facts ORDER BY f.schema_name COLLATE pg_catalog."C",f.relname COLLATE pg_catalog."C",f.conname COLLATE pg_catalog."C",f.contype::text COLLATE pg_catalog."C"),'[]'::jsonb) FROM constraint_facts f),
 'indexes',(SELECT coalesce(pg_catalog.jsonb_agg(f.facts ORDER BY f.schema_name COLLATE pg_catalog."C",f.relname COLLATE pg_catalog."C"),'[]'::jsonb) FROM index_facts f),
 'triggers',(SELECT coalesce(pg_catalog.jsonb_agg(f.facts ORDER BY f.schema_name COLLATE pg_catalog."C",f.relname COLLATE pg_catalog."C",f.tgname COLLATE pg_catalog."C"),'[]'::jsonb) FROM trigger_facts f),
