 )actual;
 v_owner := (v_raw->'ownerAnchorRaw'->>'ownerOidRaw')::pg_catalog.oid;
 v_bootstrap := (v_raw->'systemOwnerRaw'->>'ownerOidRaw')::pg_catalog.oid;
