 FOREACH v_key IN ARRAY ARRAY['builtinFunctions','builtinOperators','builtinCasts','aggregates','accessMethods','toastOperatorClasses','toastOperatorFamilies','collations'] LOOP
 IF (NOT EXISTS((SELECT x FROM jsonb_array_elements(v_writer->v_key)x) EXCEPT ALL (SELECT x FROM jsonb_array_elements(v_expected->'rawContract'->v_key)x)) AND NOT EXISTS((SELECT x FROM jsonb_array_elements(v_expected->'rawContract'->v_key)x) EXCEPT ALL (SELECT x FROM jsonb_array_elements(v_writer->v_key)x))) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='thread_history_writer_schema_invalid'; END IF;
